"""Create a non-acquisition dry-run from retained Databento metadata snapshots."""
import json
from datetime import datetime
from pathlib import Path
from scripts.prepare_nq_history import ROOT, chunks

OUT=ROOT/'results/databento-history-preparation'
def main():
    discovery=json.loads((OUT/'discovery.json').read_text())
    first=datetime.fromisoformat(discovery.get('earliest_nq_10minute_block_start',discovery.get('earliest_confirmed_nq_outright_minute')))
    last=datetime.fromisoformat(discovery['latest_complete_session_end'])
    plan=chunks(first,last)
    estimate=json.loads((OUT/'plan.json').read_text()) if (OUT/'plan.json').exists() else None
    est_cost=estimate.get('total_cost_usd') if estimate else None
    est_bytes=sum(estimate.get('estimated_bytes_by_schema',{}).values()) if estimate else None
    est_records=sum(estimate.get('estimated_records_by_schema',{}).values()) if estimate else None
    report={
      'status':('OVER_HARD_COST_LIMIT' if estimate and float(est_cost)>85 else 'AWAITING_HUMAN_REVIEW' if estimate else 'BLOCKED_PENDING_OFFICIAL_FULL_COST_ESTIMATE'),
      'dataset':'GLBX.MDP3','schema':'ohlcv-1m plus definition','adjustment':'raw unadjusted outrights',
      'availability':{'schema_start_utc':discovery['dataset_range_start'],'earliest_nq_outright_metadata_block_start_utc':discovery.get('earliest_nq_10minute_block_start',discovery.get('earliest_confirmed_nq_outright_minute')),'earliest_trading_date':discovery['earliest_trading_date'],'latest_provider_range_utc':discovery['provider_available_through'],'latest_complete_session':discovery['latest_complete_session'],'latest_complete_session_end_utc':discovery['latest_complete_session_end'],'latest_session_condition':'degraded'},
      'instrument_selection':{'input_symbology':'raw_symbol','symbols_per_chunk':'quarterly NQ outrights only (NQH/NQM/NQU/NQZ with provider raw one-digit year); no NQ.FUT parent-family spread retrieval','chunk_symbols_example':plan[-1]['requests']['ohlcv-1m']['symbols'],'overlap':'three quarterly expirations per chunk for volume-based selection; seven-day adjacent chunk overlap'},
      'chunking':{'core_calendar_days':90,'overlap_calendar_days':7,'chunk_count':len(plan),'schemas':['definition','ohlcv-1m'],'first_core_start_utc':plan[0]['core_start'],'last_core_end_utc':plan[-1]['core_end'],'bounded_request_max_calendar_days':97},
      'estimated_size_bytes':est_bytes,'estimated_records':est_records,'estimated_cost_usd':est_cost,'estimated_cost_by_schema_usd':estimate.get('cost_by_schema_usd') if estimate else None,'hard_maximum_estimated_cumulative_cost_usd':'85.00',
      'cost_estimate_status':('Official per-chunk estimates are available in plan.json; billable download is still unauthorized.' if estimate else 'UNAVAILABLE: metadata endpoint request failed with a connection error. No full-range or per-chunk official estimate was returned. Prior cached estimates cover only seven parent-symbology chunks and are stale/incompatible with this explicit raw-symbol scope; they were not extrapolated.'),
      'billable_download_authorized':False,'timeseries_or_batch_calls_made':False,
      'coverage':{'previously_accepted_sessions':10,'previously_accepted_active_minutes':13800,'unacquired_calendar_dates':5956,'full_history_usable_sessions':None,'full_history_gaps':None,'full_history_rolls':None,'full_history_rejected_observations':None},
      'unresolved_limitations':['Exact first OHLCV bar is metadata-confirmed only to a ten-minute block; current report says 2010-06-06 22:00 UTC with 115 records in the first day.','Latest complete session 2026-10-06 has Databento degraded condition and needs missing-data review.','CME holiday/DST/early-close calendars are not yet constructed across the full range.','Estimated expiry dates used to form request symbols are only for planning; normalization must use downloaded definitions and exchange-reviewed dated calendars.','No user-specific cost or byte estimate is available until Databento metadata endpoints can be reached with configured credentials.','The 85 dollar threshold is a software gate on provider estimates, not an invoice cap.'],
      'report_inputs':['results/databento-history-preparation/discovery.json','results/databento-history-preparation/dataset-range.json','docs/acceptance/databento-2026-10-07-evidence.json']}
    (OUT/'dry-run-report.json').write_text(json.dumps(report,indent=2)+'\n')
    text=f'''# Full-history NQ Databento dry run\n\n**Status: BLOCKED — no final cost estimate is available, so this plan is not ready for review or acquisition approval.** No market-data download was initiated.\n\nThe retained Databento metadata snapshot reports GLBX.MDP3 `ohlcv-1m` availability starting **2010-06-06 00:00 UTC**; NQ outright minutes are metadata-confirmed from **2010-06-06 22:00 UTC** (115 records that first UTC day). The latest provider range snapshot extends through **2026-10-07 15:47 UTC**. The latest complete elapsed session is **2026-10-06**, ending at **21:00 UTC**, but Databento marks that UTC day **degraded**. Treat that session as provisional until gaps are audited.\n\n## Proposed request scope\n\nUse `GLBX.MDP3`, raw `ohlcv-1m`, unadjusted quarterly NQ outrights selected by explicit raw symbols. Request definitions for the same contracts. Request overlapping quarterly expirations for volume-based roll selection; exclude parent-family spreads and unrelated outrights. Do not use continuous contract symbology. Exact IDs, expiry times, and mappings must come from provider definitions during the later approved acquisition.\n\nSplit the range into **{len(plan)}** contiguous 90-calendar-day core intervals with up to seven calendar days of overlap on each following request. Each request is bounded to at most 97 calendar days for OHLCV, with definitions rounded outward to whole UTC days and has a stable request hash. This preserves enough prior-session history to seed volume comparisons and makes chunks independently resumable. Deduplicate only after comparing identical contract ID and event timestamp records across overlaps.\n\n## Size and cost gate\n\n**Official estimate:** {f'${est_cost} cumulative; {est_bytes:,} estimated billable bytes; {est_records:,} estimated records.' if estimate else 'Unavailable. The initial metadata attempt failed; successful retry is still running or has not produced the final plan.'} Per-chunk cost, byte, and record estimates are preserved in plan.json when complete. The seven older cached chunk prices used parent symbology and are excluded.\n\nThe hard cumulative estimate limit is **$85.00**. Preparation estimates definition and OHLCV separately per exact chunk and sums all chunks including repeated overlap. The acquisition command verifies the frozen request hash and exact approved total, then reprices every remaining chunk before its first time-series request and stops if any repriced chunk exceeds the estimate or the $85 cap. Provider estimates are not guaranteed invoice caps.\n\n## Current coverage and acceptance state\n\nThe previous independent acceptance covers 10 sessions (13,800 active-contract minutes), one roll, and zero rejected active-series observations. From the earliest confirmed NQ trading date through October 6, 2026 there are 5,956 other calendar dates that have not been acquired; these are **unknown**, not asserted market gaps. No full-history usable-session, gap, roll, or rejection totals can be reported before acquisition and dated-calendar validation.\n\nBefore acquisition review: inspect the exact all-chunk byte, record, and cost totals in the final plan; confirm cost is at most $85; review the full historical CME calendar including DST transitions, holiday closures and early closes; investigate the degraded October 6 source condition. No time-series request should be made until the final cost and coverage are reviewed and you explicitly approve that exact plan.\n\nSee `dry-run-report.json` for machine-readable scope and limitations.\n'''
    (OUT/'dry-run-report.md').write_text(text)
    print(text)
if __name__=='__main__': main()
